-- V17 audit hardening: immutable definitions, strict approvals, current-readiness/window gates and append-only audit.
create or replace function public.guard_release_policy_definition() returns trigger language plpgsql set search_path='' as $$begin
 if new.policy_key is distinct from old.policy_key or new.version is distinct from old.version or new.name is distinct from old.name or new.risk_class is distinct from old.risk_class or new.min_assurance_score is distinct from old.min_assurance_score or new.max_stale_controls is distinct from old.max_stale_controls or new.max_high_findings is distinct from old.max_high_findings or new.max_accepted_risks is distinct from old.max_accepted_risks or new.require_ci_green is distinct from old.require_ci_green or new.ci_freshness_minutes is distinct from old.ci_freshness_minutes or new.require_rollback_plan is distinct from old.require_rollback_plan or new.approval_mode is distinct from old.approval_mode or new.evaluation_valid_minutes is distinct from old.evaluation_valid_minutes then raise exception 'release_policy_version_immutable';end if;new.updated_at:=now();return new;end;$$;
drop trigger if exists guard_release_policy_definition_trigger on public.release_policies;create trigger guard_release_policy_definition_trigger before update on public.release_policies for each row execute function public.guard_release_policy_definition();

create or replace function public.release_candidate_is_stale(p_candidate_id uuid)
returns boolean language sql security definer set search_path=''
as $$with c as(select * from public.release_candidates where id=p_candidate_id),pol as(select p.* from public.release_policies p join c on c.policy_id=p.id),latest as(select * from public.assurance_recent_runs where status='completed' order by completed_at desc nulls last limit 1),r as(select * from public.assurance_readiness)
select case when c.evaluated_at is null then true when c.expires_at<=now() then true when not pol.enabled then true when latest.id is null then true when c.assurance_bundle_hash is distinct from latest.evidence_bundle_hash then true when r.readiness_status<>'ready' or r.assurance_score<pol.min_assurance_score or r.stale_controls>pol.max_stale_controls or r.critical_open>0 or r.high_open>pol.max_high_findings or r.accepted_risks>pol.max_accepted_risks then true when pol.require_ci_green and(c.ci_status<>'success' or c.ci_observed_at is null or c.ci_observed_at<now()-make_interval(mins=>pol.ci_freshness_minutes)) then true else false end from c join pol on true left join latest on true cross join r$$;
revoke all on function public.release_candidate_is_stale(uuid) from public,anon,authenticated;grant execute on function public.release_candidate_is_stale(uuid) to service_role;

create or replace function public.decide_release_candidate(p_candidate_id uuid,p_actor_id uuid,p_decision text,p_note text,p_event_key text)
returns public.release_candidates language plpgsql security definer set search_path=''
as $$declare c public.release_candidates;pol public.release_policies;ev public.release_events;v_slot integer;v_count integer;v_window jsonb;begin
 if p_decision not in('approved','rejected') then raise exception 'invalid_decision';end if;perform pg_advisory_xact_lock(hashtextextended('release:'||p_candidate_id::text,0));
 select * into ev from public.release_events where event_key=p_event_key;if found then if ev.candidate_id<>p_candidate_id then raise exception 'event_key_conflict';end if;select * into c from public.release_candidates where id=p_candidate_id;return c;end if;
 select * into c from public.release_candidates where id=p_candidate_id for update;if not found then raise exception 'candidate_not_found';end if;select * into pol from public.release_policies where id=c.policy_id;
 if c.status<>'ready' then raise exception 'candidate_not_ready';end if;if public.release_candidate_is_stale(c.id) then raise exception 'release_evidence_stale';end if;
 select case when exists(select 1 from public.release_approvals where candidate_id=c.id) then 2 else 1 end into v_slot;if pol.approval_mode='single' then v_slot:=1;end if;
 if p_decision='rejected' then insert into public.release_approvals(candidate_id,slot,approver_id,decision,note) values(c.id,v_slot,p_actor_id,'rejected',p_note);update public.release_candidates set status='rejected',rejected_at=now(),updated_at=now() where id=c.id returning * into c;insert into public.release_events(event_key,candidate_id,event_type,actor_id,metadata) values(p_event_key,c.id,'rejected',p_actor_id,jsonb_build_object('slot',v_slot,'note',p_note));return c;end if;
 insert into public.release_approvals(candidate_id,slot,approver_id,decision,note) values(c.id,v_slot,p_actor_id,'approved',p_note);select count(*) into v_count from public.release_approvals where candidate_id=c.id and decision='approved';
 if pol.approval_mode='single' or v_count>=2 then v_window:=public.release_window_status(c.id);if coalesce((v_window->>'allowed')::boolean,false)=false then raise exception 'release_window_closed';end if;update public.release_candidates set status='approved',approved_at=now(),updated_at=now() where id=c.id returning * into c;end if;
 insert into public.release_events(event_key,candidate_id,event_type,actor_id,metadata) values(p_event_key,c.id,case when c.status='approved' then 'approved' else 'approval_added' end,p_actor_id,jsonb_build_object('slot',v_slot,'approval_mode',pol.approval_mode,'note',p_note));return c;end;$$;
revoke all on function public.decide_release_candidate(uuid,uuid,text,text,text) from public,anon,authenticated;grant execute on function public.decide_release_candidate(uuid,uuid,text,text,text) to service_role;

create or replace function public.reconcile_release_candidates(p_run_key text)
returns jsonb language plpgsql security definer set search_path=''
as $$declare c record;v_invalid integer:=0;begin for c in select * from public.release_candidates where status in('evaluated','ready','approved') loop if public.release_candidate_is_stale(c.id) then update public.release_candidates set status='expired',updated_at=now() where id=c.id and status in('evaluated','ready','approved');if found then insert into public.release_events(event_key,candidate_id,event_type,metadata) values('invalidate:'||p_run_key||':'||c.id,c.id,case when c.status='approved' then 'evaluation_invalidated' else 'expired' end,jsonb_build_object('previous_status',c.status,'reason','stale_evidence')) on conflict(event_key) do nothing;v_invalid:=v_invalid+1;end if;end if;end loop;return jsonb_build_object('invalidated',v_invalid);end;$$;
revoke all on function public.reconcile_release_candidates(text) from public,anon,authenticated;grant execute on function public.reconcile_release_candidates(text) to service_role;

create or replace function public.guard_release_audit_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'release_audit_append_only';end;$$;
drop trigger if exists release_gate_immutable_trigger on public.release_gate_results;create trigger release_gate_immutable_trigger before update or delete on public.release_gate_results for each row execute function public.guard_release_audit_immutable();
drop trigger if exists release_approval_immutable_trigger on public.release_approvals;create trigger release_approval_immutable_trigger before update or delete on public.release_approvals for each row execute function public.guard_release_audit_immutable();
drop trigger if exists release_event_immutable_trigger on public.release_events;create trigger release_event_immutable_trigger before update or delete on public.release_events for each row execute function public.guard_release_audit_immutable();
revoke update,delete on public.release_gate_results,public.release_approvals,public.release_events from service_role;
